package mapper;import entity.DieuTri;import java.sql.ResultSet;import java.sql.SQLException;public class DieuTriMapper implements RowMapper<DieuTri> {    @Override    public DieuTri mapper(ResultSet rs) {        try {            String maDieuTri = rs.getString("maDieuTri");            String tenDieuTri = rs.getString("tenDieuTri");            return new DieuTri(maDieuTri, tenDieuTri);        } catch (SQLException e) {            return null;        }    }}